import { readFileSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const nonnegativeSafeInteger = value => Number.isSafeInteger(value) && value >= 0;

export function packContext(sections, maxBytes) {
  if (!nonnegativeSafeInteger(maxBytes)) throw new Error('Invalid maxBytes');
  if (!Array.isArray(sections)) throw new Error('sections must be an array');

  const ids = new Set();
  const entries = [];
  // Validate and snapshot every entry before making any packing decisions.
  for (let index = 0; index < sections.length; index++) {
    if (!Object.hasOwn(sections, index)) throw new Error('Sparse sections array');
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error('Invalid section');
    }
    for (const field of ['id', 'text', 'priority', 'required']) {
      if (!Object.hasOwn(section, field)) throw new Error(`Missing ${field}`);
    }
    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0 || typeof text !== 'string' ||
        !nonnegativeSafeInteger(priority) || typeof required !== 'boolean') {
      throw new Error('Invalid section fields');
    }
    if (ids.has(id)) throw new Error('Duplicate section ID');
    ids.add(id);
    const frame = '### ' + JSON.stringify(id) + '\n' + text + '\n';
    entries.push({ id, priority, required, index, frame, cost: Buffer.byteLength(frame, 'utf8') });
  }

  let bytes = 0;
  const frames = [];
  const included = [];
  const selected = new Set();
  const include = entry => {
    bytes += entry.cost;
    frames.push(entry.frame);
    included.push(entry.id);
    selected.add(entry.id);
  };
  for (const entry of entries) {
    if (!entry.required) continue;
    if (entry.cost > maxBytes - bytes) throw new Error('Required sections exceed budget');
    include(entry);
  }
  const optional = entries.filter(entry => !entry.required)
    .sort((a, b) => b.priority - a.priority || a.index - b.index);
  for (const entry of optional) {
    if (entry.cost <= maxBytes - bytes) include(entry);
  }
  return {
    text: frames.join(''),
    bytes,
    included,
    omitted: entries.filter(entry => !entry.required && !selected.has(entry.id)).map(entry => entry.id)
  };
}

function isMain() {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(process.argv[1]) === fileURLToPath(import.meta.url);
  } catch {
    return false;
  }
}

if (isMain()) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node context-packet.js INPUT_JSON_FILE');
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      throw new Error('Input must be an object');
    }
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (error) {
    process.stderr.write((error instanceof Error ? error.message : String(error)) + '\n');
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, priority = 0, required = false) => ({ id, text: '', priority, required });
const frame = s => '### ' + JSON.stringify(s.id) + '\n' + s.text + '\n';

test('safe integer boundaries and full invalid-field validation at zero budget', () => {
  const max = Number.MAX_SAFE_INTEGER;
  assert.deepEqual(packContext([section('a', max)], max).included, ['a']);
  for (const value of [-1, 0.5, max + 1, Infinity, NaN, '0', null, undefined, 1n]) {
    assert.throws(() => packContext([], value), Error);
    assert.throws(() => packContext([{ ...section('a'), priority: value }], 0), Error);
  }
  for (const field of ['id', 'text', 'priority', 'required']) {
    const s = section('a');
    delete s[field];
    assert.throws(() => packContext([s], 0), Error);
    assert.throws(() => packContext([{ ...section('a'), [field]: undefined }], 0), Error);
  }
  for (const s of [null, [], 1, 'x', {}, { ...section('a'), id: '' },
    { ...section('a'), text: 1 }, { ...section('a'), required: 0 }]) {
    assert.throws(() => packContext([s], 0), Error);
  }
  for (const value of [null, {}, 'x', new Array(2)]) {
    assert.throws(() => packContext(value, 0), Error);
  }
  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
});

test('required order, optional tie order, omitted input order and exact framing', () => {
  const entries = [section('low', 1), section('high', 99), section('r1', 0, true),
    section('r2', 100, true), section('x', 5), section('y', 5)];
  entries[0].text = 'z'.repeat(200);
  entries[1].text = 'z'.repeat(200);
  const expected = [entries[2], entries[3], entries[4], entries[5]].map(frame).join('');
  entries.forEach(Object.freeze);
  Object.freeze(entries);
  assert.deepEqual(packContext(entries, Buffer.byteLength(expected)), {
    text: expected, bytes: Buffer.byteLength(expected), included: ['r1', 'r2', 'x', 'y'], omitted: ['low', 'high']
  });
  const special = ['__proto__', 'A', 'a', ' \n\u0000雪"'].map(id => ({ ...section(id), text: ' é\r\n😀\n ' }));
  const text = special.map(frame).join('');
  assert.deepEqual(packContext(special, Buffer.byteLength(text)), {
    text, bytes: Buffer.byteLength(text), included: special.map(s => s.id), omitted: []
  });
  assert.throws(() => packContext([section('a', 0, true), section('b', 0, true)], 10), Error);
});

test('CLI success, import silence, and every error class', () => {
  const dir = mkdtempSync(join(tmpdir(), 'context-packet-'));
  const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  const failure = args => {
    const result = run(args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.trim().length > 0);
  };
  try {
    const path = join(dir, 'input.json');
    const input = { sections: [{ ...section('雪'), text: 'é' }], maxBytes: 100, extra: true };
    writeFileSync(path, JSON.stringify(input));
    const result = run([path]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(packContext(input.sections, input.maxBytes)) + '\n');
    failure([]);
    failure([path, path]);
    failure([join(dir, 'missing.json')]);
    for (const data of ['{', 'null', '[]', '{}', JSON.stringify({ sections: [section('a', 0, true)], maxBytes: 0 }),
      JSON.stringify({ sections: [section('a')], maxBytes: Number.MAX_SAFE_INTEGER + 1 })]) {
      writeFileSync(path, data);
      failure([path]);
    }
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
      `import ${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)}`], { encoding: 'utf8' });
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

